"use client";

import React, { useRef, useState, useEffect } from "react";
import { motion, useSpring, useMotionValue } from "motion/react";
import { ReactLenis } from "lenis/react";
import "./device.css";

export interface DeviceProps {
  /** Image URL for the device screen */
  image?: string;

  /** Scale factor for the device size (0.5 to 1.5) */
  scale?: number;

  /** Whether the image can scroll vertically (for long screenshots) */
  isScrollable?: boolean;

  /** Enable parallax effect on hover */
  enableParallax?: boolean;

  /** Parallax movement strength in pixels (default: 15) */
  parallaxStrength?: number;

  /** Enable rotation effect on hover */
  enableRotate?: boolean;

  /** Rotation strength in degrees (default: 3) */
  rotateStrength?: number;

  /** Auto-animate with simulated cursor movement */
  autoAnimate?: boolean;

  /** Additional CSS classes for the wrapper */
  className?: string;

  /** Content to display inside the device screen */
  children?: React.ReactNode;
}

const Device = React.forwardRef<HTMLDivElement, DeviceProps>(
  (
    {
      image = "https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=800&q=80",
      scale = 1,
      isScrollable = false,
      enableParallax = true,
      parallaxStrength = 15,
      enableRotate = true,
      rotateStrength = 3,
      autoAnimate = false,
      className,
      children,
    },
    ref,
  ) => {
    const deviceRef = useRef<HTMLDivElement>(null);
    const [isHovering, setIsHovering] = useState(false);
    const animationFrameRef = useRef<number | undefined>(undefined);

    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const rotateX = useMotionValue(0);
    const rotateY = useMotionValue(0);
    const rotateZ = useMotionValue(0);

    const springX = useSpring(x, {
      stiffness: 200,
      damping: 25,
      mass: 0.5,
    });
    const springY = useSpring(y, {
      stiffness: 200,
      damping: 25,
      mass: 0.5,
    });
    const springRotateX = useSpring(rotateX, {
      stiffness: 200,
      damping: 25,
      mass: 0.5,
    });
    const springRotateY = useSpring(rotateY, {
      stiffness: 200,
      damping: 25,
      mass: 0.5,
    });
    const springRotateZ = useSpring(rotateZ, {
      stiffness: 200,
      damping: 25,
      mass: 0.5,
    });

    useEffect(() => {
      if (!autoAnimate) return;

      let time = 0;
      const animate = () => {
        time += 0.005;

        const mouseX = Math.sin(time) * 0.8;
        const mouseY = Math.sin(time * 1.3) * 0.6;

        if (enableParallax) {
          x.set(mouseX * parallaxStrength);
          y.set(-mouseY * parallaxStrength);
        }

        if (enableRotate) {
          rotateX.set(-mouseY * rotateStrength);
          rotateY.set(mouseX * rotateStrength);
          rotateZ.set(mouseX * rotateStrength * 0.5);
        }

        animationFrameRef.current = requestAnimationFrame(animate);
      };

      animationFrameRef.current = requestAnimationFrame(animate);

      return () => {
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
        }
      };
    }, [
      autoAnimate,
      enableParallax,
      enableRotate,
      parallaxStrength,
      rotateStrength,
      x,
      y,
      rotateX,
      rotateY,
      rotateZ,
    ]);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (autoAnimate || !deviceRef.current) return;

      const rect = deviceRef.current.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;

      const mouseX = (e.clientX - centerX) / (rect.width / 2);
      const mouseY = (e.clientY - centerY) / (rect.height / 2);

      if (enableParallax) {
        x.set(mouseX * parallaxStrength);
        y.set(-mouseY * parallaxStrength);
      }

      if (enableRotate) {
        rotateX.set(-mouseY * rotateStrength);
        rotateY.set(mouseX * rotateStrength);
        rotateZ.set(mouseX * rotateStrength * 0.5);
      }
    };

    const handleMouseEnter = () => {
      if (!autoAnimate) {
        setIsHovering(true);
      }
    };

    const handleMouseLeave = () => {
      if (!autoAnimate) {
        setIsHovering(false);
        x.set(0);
        y.set(0);
        rotateX.set(0);
        rotateY.set(0);
        rotateZ.set(0);
      }
    };

    const scaleStyle = {
      transform: `scale(${scale})`,
      transformOrigin: "center center",
    };

    const screenContent = isScrollable ? (
      <ReactLenis
        options={{
          lerp: 0.1,
          duration: 1.2,
          smoothWheel: true,
        }}
        className="device-content device-content-scrollable"
      >
        {children ? (
          children
        ) : (
          <img
            src={image}
            alt="Device screen"
            className="device-screen-image device-screen-image-scrollable"
            draggable={false}
          />
        )}
      </ReactLenis>
    ) : (
      <div className="device-content">
        {children ? (
          children
        ) : (
          <img
            src={image}
            alt="Device screen"
            className="device-screen-image"
            draggable={false}
          />
        )}
      </div>
    );

    return (
      <div
        ref={ref}
        className={`device-wrapper ${className || ""}`}
        style={scaleStyle}
      >
        <motion.div
          ref={deviceRef}
          onMouseMove={handleMouseMove}
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          style={{
            x: springX,
            y: springY,
            rotateX: springRotateX,
            rotateY: springRotateY,
            rotateZ: springRotateZ,
            transformStyle: "preserve-3d",
          }}
          animate={{
            scale: isHovering || autoAnimate ? 1.02 : 1,
          }}
          transition={{
            scale: {
              type: "spring",
              stiffness: 300,
              damping: 25,
            },
          }}
          className="device-motion-wrapper"
        >
          <div
            className="device-body"
            style={{
              boxShadow:
                isHovering || autoAnimate
                  ? "0 30px 60px -12px rgba(0, 0, 0, 0.3), 0 18px 36px -18px rgba(0, 0, 0, 0.25)"
                  : "0 0 2rem 1rem rgba(0, 0, 0, 0.1)",
            }}
          >
            {screenContent}

            <div className="device-dynamic-island">
              <div className="device-sensors">
                <div className="device-sensor" />
                <div className="device-sensor" />
              </div>

              <div className="device-speaker-grill">
                {[...Array(8)].map((_, i) => (
                  <div key={i} className="device-speaker-grill-line" />
                ))}
              </div>

              <div className="device-camera" />
            </div>

            <div className="device-button device-button-silent" />

            <div className="device-button device-button-volume-up" />

            <div className="device-button device-button-volume-down" />

            <div className="device-button device-button-power" />

            <div className="device-layer device-layer-1" />

            <div className="device-layer device-layer-2" />

            <div className="device-layer device-layer-gradient-1" />

            <div className="device-layer device-layer-gradient-2" />
          </div>
        </motion.div>
      </div>
    );
  },
);

Device.displayName = "Device";

export default Device;

.device-wrapper {
  position: relative;
  display: inline-block;
}

.device-body {
  position: relative;
  flex-shrink: 0;
  width: 35.6rem;
  height: 72.2rem;
  border-radius: 6rem;
  display: flex;
  justify-content: center;
  background-color: #000000;
  user-select: none;
  transition: box-shadow 300ms ease;
}

.device-body.device-hover:hover {
  box-shadow: none;
  transform: scale(0.95);
}

.device-content {
  position: absolute;
  inset: 1.9rem;
  overflow: hidden;
  border-radius: 5rem;
}

.device-content-scrollable {
  overflow-y: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.device-content-scrollable::-webkit-scrollbar {
  display: none;
}

.device-screen-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
  user-select: none;
}

.device-screen-image-scrollable {
  height: auto;
  min-height: 100%;
}

.device-dynamic-island {
  position: absolute;
  top: 2.8rem;
  left: 50%;
  transform: translateX(-50%);
  width: 12.6rem;
  height: 3.7rem;
  background-color: #000000;
  border-radius: 3rem;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2.4rem;
}

.device-camera {
  width: 1.1rem;
  height: 1.1rem;
  background-color: #1a1a2e;
  border-radius: 50%;
  border: 0.15rem solid #0a0a15;
  box-shadow: inset 0 0 0.3rem rgba(0, 100, 200, 0.5);
  flex-shrink: 0;
}

.device-speaker-grill {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.15rem;
  margin: 0 1.2rem;
}

.device-speaker-grill-line {
  width: 0.15rem;
  height: 1.2rem;
  background-color: #0a0a15;
  border-radius: 999px;
  opacity: 0.6;
}

.device-sensors {
  display: flex;
  gap: 0.4rem;
  flex-shrink: 0;
}

.device-sensor {
  width: 0.4rem;
  height: 0.4rem;
  background-color: #1a1a2e;
  border-radius: 50%;
  border: 0.1rem solid #0a0a15;
}

.device-button {
  position: absolute;
  width: 0.3rem;
  background-color: #484848;
  border-top-left-radius: 0.3rem;
  border-bottom-left-radius: 0.3rem;
  border: 0.1rem solid rgba(0, 0, 0, 0.1);
  border-right: none;
}

.device-button-silent {
  top: 9.8rem;
  left: -0.2rem;
  height: 2.5rem;
}

.device-button-volume-up {
  top: 15rem;
  left: -0.2rem;
  height: 5rem;
}

.device-button-volume-down {
  top: 21.6rem;
  left: -0.2rem;
  height: 5rem;
}

.device-button-power {
  top: 16.9rem;
  right: -0.3rem;
  height: 5rem;
  transform: rotate(180deg);
}

.device-layer {
  position: absolute;
  pointer-events: none;
}

.device-layer-1 {
  inset: 0;
  border: 0.4rem solid #484848;
  border-radius: 6rem;
}

.device-layer-2 {
  inset: 0.3rem;
  border: 1.6rem solid #000000;
  border-radius: 5.6rem;
}

.device-layer-gradient-1 {
  inset: 1.1rem;
  border: 0.3rem solid #484848;
  border-radius: 5rem;
  filter: blur(1px);
  opacity: 0.5;
}

.device-layer-gradient-2 {
  inset: 0.7rem;
  border: 0.4rem solid #bcbcbc;
  border-radius: 5.6rem;
  opacity: 0.5;
  filter: blur(1px);
}

@media (max-width: 600px) {
  .device-body {
    transform: scale(0.65);
  }

  .device-body.device-hover:hover {
    transform: scale(0.6);
  }
}

@media (max-height: 800px) {
  .device-body {
    transform: scale(0.77);
  }

  .device-body.device-hover:hover {
    transform: scale(0.68);
  }
}

@media (max-height: 630px) {
  .device-body {
    transform: scale(0.53);
  }

  .device-body.device-hover:hover {
    transform: scale(0.48);
  }
}
